"use strict";(globalThis.webpackChunkelemental_selenium||=[]).push([[60872],{681656(t){t.exports=JSON.parse('{"tag":{"label":"network","permalink":"/tips/tags/network","allTagsPath":"/tips/tags","count":3,"items":[{"id":"blocklist/66-blocklist","title":"Block Slow Third-Party Requests","description":"Pages load resources that are not relevant to the functionality we test (analytics, social widgets, ads). When they load slowly, they slow down our tests or make them fail. WebDriver BiDi lets the test block them.","permalink":"/tips/66-blocklist"},{"id":"mock-network-responses/20-mock-network-responses","title":"How to Mock Network Responses","description":"A page that loads its data from an API is hard to test: the API can be slow, down, or return data that changes. The test can answer the API calls itself, with the data it chooses, and check how the page shows it.","permalink":"/tips/20-mock-network-responses"},{"id":"limit-bandwidth/64-limit-bandwidth","title":"Test on a Slow Network","description":"With Selenium we can test our application on different browsers. But how does it behave on a slow connection? Chrome can limit its own network, so the tests can find out.","permalink":"/tips/64-limit-bandwidth"}],"unlisted":false}}')}}]);